async def iter(self) -> AsyncIterator[Tuple[int, _T]]:
    """Perform file I/O and return async iterator of results"""

    self._start_tasks()

    while self._pending:
        done, self._pending = await asyncio.wait(
            self._pending, return_when=asyncio.FIRST_COMPLETED)

        exceptions = []

        for task in done:
            try:
                offset, size, count, result = task.result()
                yield offset, result

                if count < size:
                    self._pending.add(asyncio.ensure_future(
                        self._start_task(offset+count, size-count)))
            except SFTPEOFError:
                pass
            except (OSError, SFTPError) as exc:
                exceptions.append(exc)

        if exceptions:
            for task in self._pending:
                task.cancel()

            raise exceptions[0]

        self._start_tasks()

def walk_xauth(auth_path: str) -> Iterable[SSHXAuthorityEntry]:
    """Walk the entries in an Xauthority file"""

    def _read_bytes(n: int) -> bytes:
        """Read exactly n bytes"""

        data = auth_file.read(n)

        if len(data) != n:
            raise EOFError

        return data

    def _read_uint16() -> int:
        """Read a 16-bit unsigned integer"""

        return int.from_bytes(_read_bytes(2), 'big')

    def _read_string() -> bytes:
        """Read a string"""

        return _read_bytes(_read_uint16())

    try:
        with open(auth_path, 'rb') as auth_file:
            while True:
                try:
                    family = _read_uint16()
                except EOFError:
                    break

                try:
                    yield SSHXAuthorityEntry(family, _read_string(),
                                             _read_string(), _read_string(),
                                             _read_string())
                except EOFError:
                    raise ValueError('Incomplete Xauthority entry') from None
    except OSError:
        pass

def _read_bytes(n: int) -> bytes:
    """Read exactly n bytes"""

    data = auth_file.read(n)

    if len(data) != n:
        raise EOFError

    return data

def _read_uint16() -> int:
    """Read a 16-bit unsigned integer"""

    return int.from_bytes(_read_bytes(2), 'big')

def _read_string() -> bytes:
    """Read a string"""

    return _read_bytes(_read_uint16())

