    """Return output from the process"""

    recv_buf = self._recv_buf[datatype]

    if recv_buf and isinstance(recv_buf[-1], Exception):
        recv_buf, self._recv_buf[datatype] = recv_buf[:-1], recv_buf[-1:]
    else:
        self._recv_buf[datatype] = []

